// nested callbacks vs await
async function loadUser(id) {
  const user = await fetch(`/api/users/${id}`).then((r) => r.json());
  const posts = await fetch(`/api/posts?user=${user.id}`).then((r) => r.json());
  return { user, posts };
}

async function getJson(url) {
  const res = await fetch(url);
  if (!res.ok) throw new Error(String(res.status));
  return res.json();
}

// sequential
const a = await fetchA();
const b = await fetchB();

// parallel
const [a2, b2] = await Promise.all([fetchA(), fetchB()]);

const ac = new AbortController();
fetch('/api/data', { signal: ac.signal }).catch((err) => {
  if (err.name === 'AbortError') return;
  throw err;
});
ac.abort();

let seq = 0;
async function search(q) {
  const id = ++seq;
  const data = await fetch(`/search?q=${q}`).then((r) => r.json());
  if (id !== seq) return; // stale
  render(data);
}
